SELECT store_sales.store_id, DATE_TRUNC('MONTH', store_sales.sale_date) AS sale_month, COUNT(inventory.quantity) AS quantity_count, COUNT(DISTINCT inventory.quantity) AS unique_products FROM inventory INNER JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id GROUP BY store_sales.store_id, DATE_TRUNC('MONTH', store_sales.sale_date)
